"""Partial-success TTS: actual PCM kept, failures accounted for per chunk."""
from __future__ import annotations

import io
import json
import struct
import unittest
import wave
from unittest.mock import patch

from voxweavetts.processing import process_text
from voxweavetts.speech import (
    AllChunksFailed, EngineInfo, ENGINE_ID, render_wav,
)
from voxweavetts.speech_coordinator import SpeechCoordinator
from voxweavetts.tts_model_inputs import collect_model_inputs


def plan():
    # Distinct speech segments are generated by the same public processing
    # rules; the model only fails on the replacement's middle segment.
    return process_text(
        "first bad third",
        rules=[{"match": "bad", "mode": "replace", "spoken": "bad",
                "display": "bad"}],
    )


class FlakyEngine:
    id = "flaky"
    sample_rate = 24000

    def __init__(self, broken=("bad",)):
        self.broken = set(broken)
        self.calls = []

    def generate(self, text, speed):
        self.calls.append(text)
        if any(piece in text for piece in self.broken):
            raise RuntimeError("this is private model input, never log")
        return struct.pack("<h", 1200) * 240


class PartialTTSTests(unittest.TestCase):
    def test_one_failed_chunk_keeps_all_successful_pcm_in_order(self):
        engine = FlakyEngine()
        speech_plan = plan()
        output, details = render_wav(speech_plan, engine=engine)
        with wave.open(io.BytesIO(output), "rb") as wav:
            self.assertEqual(wav.getnframes(), 480)
            self.assertEqual(wav.getframerate(), 24000)
        self.assertEqual(details["chunk_success"], [True, False, True])
        self.assertEqual(len(engine.calls), 3)
        self.assertEqual(len(details["segments"]), 3)
        self.assertEqual(details["segments"][1]["start_ms"],
                         details["segments"][1]["end_ms"])
        self.assertNotIn("private model input",str(details))

    def test_all_failed_even_if_silence_remains_is_not_playable(self):
        bad = FlakyEngine(broken=("first","bad","third"))
        with self.assertRaises(AllChunksFailed):
            render_wav(plan(), engine=bad)
        # A silence segment does not turn a 100%-failed TTS into success.
        silence=process_text("fail !",rules=[
            {"match":"!","mode":"silence","silence_ms":100},
        ])
        with self.assertRaises(AllChunksFailed):
            render_wav(silence,engine=FlakyEngine(broken=("fail",)))

    def test_mixed_language_failure_keeps_thai_and_marks_english_failure(self):
        from voxweavetts.speech import render_wav
        import voxweavetts.speech as speech
        def info(key):
            if key not in ("thai", "english"):
                raise ValueError("unknown test engine")
            return EngineInfo(
                id=key, label=key, language="multi", sample_rate=24000,
                voice_id="thai_voice" if key=="thai" else "en_voice",
                voice_options=(("thai_voice" if key=="thai" else "en_voice",
                                "test voice"),),
                assets_ready=True,runtime_ready=True,capabilities={},
            )
        created=[]
        def engine_factory(key,seed):
            engine=FlakyEngine(broken=("bad",)) if key=="english" else FlakyEngine(broken=())
            engine.id=key
            created.append(engine)
            return engine
        p=process_text("ไทย bad ไทย")
        params=dict(engine_id="thai",voice_id="thai_voice",
                    language_voice_routes={
                      "th":{"engine_id":"thai","voice_id":"thai_voice"},
                      "en":{"engine_id":"english","voice_id":"en_voice"},
                    })
        with patch.object(speech,"get_engine_info",side_effect=info),patch.object(
            speech,"create_voice_engine",side_effect=engine_factory
        ):
            data,details=render_wav(p,**params)
        with wave.open(io.BytesIO(data),"rb") as wav:
            self.assertEqual(wav.getnframes(),480)
        self.assertEqual(details["chunk_success"],[True,False,True])
        models=collect_model_inputs(p,params)
        self.assertEqual(len(models),len(details["chunk_success"]))
        self.assertEqual([x["language"] for x in models],["th","en","th"])
        self.assertNotIn("this is private model input",json.dumps(details))
        self.assertEqual({x["id"] for x in details["voices_used"]
                          if "id" in x},set())

    def test_explicit_routes_work_with_uninstalled_default_model(self):
        import voxweavetts.speech as speech
        p=process_text("ไทย hello")
        def info(key):
            if key not in ("default","routed-th","routed-en"):
                raise ValueError("unknown test engine")
            return EngineInfo(
                id=key,label=key,language="multi",sample_rate=24000,
                voice_id="test_voice",voice_options=(("test_voice","Test"),),
                assets_ready=key!="default",runtime_ready=key!="default",
                capabilities={}
            )
        with (patch.object(speech,"get_engine_info",side_effect=info),
              patch.object(speech,"create_voice_engine",
                           side_effect=lambda engine,seed:FlakyEngine(broken=()))):
            _wav,info_data=render_wav(
                p,engine_id="default",voice_id="test_voice",
                language_voice_routes={
                    "th":{"engine_id":"routed-th","voice_id":"test_voice"},
                    "en":{"engine_id":"routed-en","voice_id":"test_voice"},
                }
            )
        self.assertEqual(info_data["chunk_success"],[True,True])
        self.assertEqual(info_data["sample_rate"],24000)

    def test_system_memory_exhaustion_is_never_silently_swallowed(self):
        class NoMemory(FlakyEngine):
            def generate(self,text,speed):
                raise MemoryError("insufficient memory")
        with self.assertRaises(MemoryError):
            render_wav(plan(),engine=NoMemory())

    def test_coordinator_reports_private_success_flags_and_public_safe_counts(self):
        engine=FlakyEngine()
        c=SpeechCoordinator(render_wav)
        try:
            created=c.submit(
                plan(),engine_id=ENGINE_ID,voice_id="thai_som",
                render_args={"engine":engine}
            )
            job=c.wait(created["speech_id"],timeout=5)
            self.assertEqual(job["state"],"ready",job)
            self.assertEqual(job["successful_chunks"],2)
            self.assertEqual(job["failed_chunks"],1)
            self.assertTrue(job["partial_failure"])
            inputs=c.get_model_inputs(created["speech_id"])
            self.assertEqual([x["success"] for x in inputs["inputs"]],
                             [True,False,True])
            self.assertNotIn("this is private model input",json.dumps(job))
            self.assertNotIn("this is private model input",json.dumps(c.events(created["speech_id"])))
            self.assertTrue(c.audio(created["speech_id"]).startswith(b"RIFF"))
        finally:
            c.close()

    def test_coordinator_all_failed_returns_machine_readable_error(self):
        engine=FlakyEngine(broken=("first","bad","third"))
        c=SpeechCoordinator(render_wav)
        try:
            created=c.submit(
                plan(),engine_id=ENGINE_ID,voice_id="thai_som",
                render_args={"engine":engine}
            )
            job=c.wait(created["speech_id"],timeout=5)
            self.assertEqual(job["state"],"failed")
            self.assertEqual(job["error"],"all_tts_chunks_failed")
            self.assertEqual(job["successful_chunks"],0)
            self.assertEqual(job["failed_chunks"],3)
            self.assertEqual([x["success"] for x in
                              c.get_model_inputs(created["speech_id"])["inputs"]],
                             [False]*3)
        finally:
            c.close()


if __name__=="__main__":
    unittest.main()
